<?php
if(session_status()===PHP_SESSION_NONE)session_start();require_once '../includes/config.php';require_once '../includes/database.php';require_once '../includes/auth.php';$db=new Database();$auth=new Auth($db);$auth->requireRole('passenger');$pdo=$db->getConnection();$uid=$auth->getUserId();$code=trim($_GET['code']??'');$bag=null;$history=[];$err='';if($code!==''){ $stmt=$pdo->prepare("SELECT b.*,f.flight_number FROM baggage b JOIN flights f ON b.flight_id=f.id WHERE b.baggage_code=? AND b.passenger_id=?");$stmt->execute([$code,$uid]);$bag=$stmt->fetch();if($bag){$stmt=$pdo->prepare("SELECT tl.*,l.location_name FROM tracking_logs tl LEFT JOIN locations l ON tl.location_id=l.id WHERE tl.baggage_id=? ORDER BY tl.actual_scan_time DESC");$stmt->execute([$bag['id']]);$history=$stmt->fetchAll();}else $err='Baggage not found for this account.';}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Track Baggage</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body class="bg-light"><div class="container py-5"><a href="dashboard.php">← Dashboard</a><h2 class="mt-2">Track Baggage</h2><form class="row g-2 my-3"><div class="col-md-8"><input class="form-control" name="code" value="<?=htmlspecialchars($code)?>" placeholder="Baggage code" required></div><div class="col-md-4"><button class="btn btn-primary w-100">Search</button></div></form><?php if($err):?><div class="alert alert-warning"><?=htmlspecialchars($err)?></div><?php endif;?><?php if($bag):?><div class="card mb-3"><div class="card-body"><h4><?=htmlspecialchars($bag['baggage_code'])?></h4><p>Flight: <?=htmlspecialchars($bag['flight_number'])?> · Status: <strong><?=htmlspecialchars($bag['status'])?></strong> · Weight: <?=htmlspecialchars($bag['weight'])?> kg</p></div></div><div class="card"><div class="card-header">Tracking history</div><ul class="list-group list-group-flush"><?php foreach($history as $h):?><li class="list-group-item"><strong><?=htmlspecialchars($h['status'])?></strong> · <?=htmlspecialchars($h['location_name']??'Unknown location')?> · <?=htmlspecialchars($h['actual_scan_time']??'')?></li><?php endforeach;?></ul></div><?php endif;?></div></body></html>